import{_ as n,l as r,o as e,c as l,v as t,p as d,x as o,d as i,i as c,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"对齐与非对齐访问","description":"","frontmatter":{"title":"对齐与非对齐访问","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/alignment-access.md","filePath":"cs/alignment-access.md","lastUpdated":1789023840000}'),p={name:"cs/alignment-access.md"};function E(h,a,S,m,I,_){const s=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="对齐与非对齐访问" tabindex="-1">对齐与非对齐访问 <a class="header-anchor" href="#对齐与非对齐访问" aria-label="Permalink to &quot;对齐与非对齐访问&quot;">​</a></h1><div class="epigraph"><p>自然对齐让一次访存落在单次总线事务与单次缓存行内；非对齐或被硬件拆成两拍，或 trap 到固件，原子与 SIMD 往往更严。</p><footer>—— 据 The RISC-V Instruction Set Manual；ARM ARM；Intel SDM；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/endianness">上一课</a>钉了字节在字内的次序。次序假定「这一次 load 读的就是那四个字节」。缺口是 <strong>对齐</strong>：地址是否为宽度的倍数，以及 ISA 对违规的态度——硬件修复、异常，还是原子直接拒绝。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自然对齐：<code>N</code> 字节对象要求 <code>addr ≡ 0 (mod N)</code>。未对齐时，访问可能跨缓存行甚至跨页：一次逻辑 load 变成两次翻译、两次填充。<a href="/cs/riscv-compressed">压缩指令</a> 已要求 16 位取指对齐；数据侧同类问题更大，因为 <code>ld</code> 是 8 字节。</p><p>x86：普通访存允许非对齐，罚的是周期；<code>EFLAGS.AC</code> 可打开对齐检查。A64：普通内存上多数 load/store 可非对齐；独占监视器与部分设备内存更严。RISC-V：实现可硬件处理、可 trap 到 M 态模拟，规范不强制同一种性能。缺口不是端序，而是<strong>这条路径在手册里是否合法、是否原子</strong>。</p><p><a href="/cs/lr-sc-cas">LR/SC 与 CAS</a> 通常要求自然对齐，否则保留集与缓存行排他没有定义。SSE 的 <code>movaps</code> 要求 16 字节；<code>movups</code> 才放松——<a href="/cs/simd-extensions">SIMD</a> 把对齐写进助记符。</p><h3 id="对齐不是「编译器多插几个-nop」" tabindex="-1">对齐不是「编译器多插几个 nop」 <a class="header-anchor" href="#对齐不是「编译器多插几个-nop」" aria-label="Permalink to &quot;对齐不是「编译器多插几个 nop」&quot;">​</a></h3><p>指令对齐影响取指打包；数据对齐影响 ABI 的 <code>alignof</code> 与结构体填充。把两者混成「好看」，栈上 <code>double</code> 未按 ABI 对齐时，AAPCS/SysV 直接未定义或罚崩。</p><p><span class="marginnote">RISC-V 非特权手册的 misaligned。ARM ARM 的 Alignment fault。Intel SDM 的 Alignment Check 与非对齐惩罚。CA:AQA 用对齐解释缓存与总线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器按 ABI 给标量与结构体填填充字节；packed 结构显式放弃对齐，生成字节拼装或非对齐 load。内核与驱动访问 MMIO 必须用架构允许的宽度与对齐，否则设备与总线协议先坏。跨页非对齐：可能两次缺页，<a href="/cs/sv39-page-table">Sv39</a> 走访两次。</p>',12)),(e(),d(A,null,{default:o(()=>[c(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADDR%5B%22%E6%9C%89%E6%95%88%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20OK%7B%22%E8%87%AA%E7%84%B6%E5%AF%B9%E9%BD%90%3F%22%7D%0A%20%20OK%20--%3E%7C%22%E6%98%AF%22%7C%20ONE%5B%22%E4%B8%80%E6%AC%A1%E7%BF%BB%E8%AF%91%E4%B8%8E%E4%B8%80%E6%AC%A1%E5%A1%AB%E5%85%85%22%5D%0A%20%20OK%20--%3E%7C%22%E5%90%A6%22%7C%20SPLIT%5B%22%E6%8B%86%E8%AE%BF%E9%97%AE%E6%88%96%20trap%22%5D%0A%20%20SPLIT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AABI%20%E6%8A%8A%E5%AF%B9%E9%BD%90%E5%86%99%E6%88%90%E5%90%88%E5%90%8C%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 <a href="/cs/fence-instructions">fence</a>：拆成两次的 store 之间仍受内存模型约束；不能假设设备看见一次原子字写。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ISA 对照单元快结束：编码、特权、向量、端序、对齐都是硬件保证的边界。软件还要在这些边界上叠一层<strong>调用约定与目标文件合同</strong>——同一颗核、同一 ISA，SysV 与 Windows x64 仍不能互调。下一课把 ISA 收成 ABI 边界，并交给微结构进阶：前端看到的分支，是编译器按这份合同发出来的。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 MMIO 设备的访问宽度表抄来，不保证软模拟非对齐的延迟。不进入数据库列存的对齐 SIMD 作业全文。</p><p>后课默认：原子与许多 SIMD 要自然对齐；普通标量在 x86/A64 上常可非对齐但有代价；RISC-V 实现可选 trap。下一课 ISA 作为 ABI 边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自然对齐服务单次缓存行与原子性。</li><li>非对齐：硬件拆、trap，或指令直接不允许。</li><li>端序与对齐是两件独立的 ISA 事实。</li><li>出处：RISC-V ISA；ARM ARM；Intel SDM；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const u=n(p,[["render",E]]);export{f as __pageData,u as default};
